from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub()
motor = Motor(Port.B, Direction.COUNTERCLOCKWISE)
motor_2 = Motor(Port.A, Direction.CLOCKWISE)
drive_base = DriveBase(motor, motor_2, 87, 120)


# The main program starts here.
drive_base.straight(-203.2)
drive_base.turn(-80)
drive_base.straight(-1300)
drive_base.turn(-120)
drive_base.straight(-200)
drive_base.straight(375)
drive_base.straight(-200)
drive_base.turn(120)
drive_base.settings(straight_speed=1000)
drive_base.straight(1300)
raise SystemExit
